         "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

 var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY");
 var searchEngineId = Environment.GetEnvironmentVariable("SEARCH_ENGINE_ID");

 bool liveSearchEnabled = !string.IsNullOrEmpty(searchApiKey)
     && !string.IsNullOrEmpty(searchEngineId);

 if (!liveSearchEnabled)
     Console.WriteLine("[info] SEARCH_API_KEY / SEARCH_ENGINE_ID not set – using simulated web search.\n");

 // --- Tools -------------------------------------------------------------------

 var notes = new NoteStore();
 var webSearch = new WebSearchService(searchApiKey, searchEngineId, liveSearchEnabled);

 var searchTool = AIFunctionFactory.Create(
     ([Description("The search query")] string query) => webSearch.SearchAsync(query),
     "web_search",
     "Search the web for information on a topic. Returns a list of results with title, snippet, and URL.");

 var addNoteTool = AIFunctionFactory.Create(
     ([Description("Short label for the note")] string title,
      [Description("The note content")] string content) =>
     {
         notes.Add(title, content);
         return $"Note '{title}' saved. You now have {notes.Count} note(s).";
     },
     "add_note",
     "Save a research note for later reference.");

 var listNotesTool = AIFunctionFactory.Create(
     () => notes.Count == 0
         ? "No notes yet."
         : string.Join("\n\n", notes.All.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}")),
     "list_notes",
     "List all saved research notes.");

 // --- Agent loop --------------------------------------------------------------

 var client = new OpenAIClient(openAiKey)
     .GetChatClient("gpt-4o")
     .AsIChatClient();

 var chatOptions = new ChatOptions
 {
     Tools = [searchTool, addNoteTool, listNotesTool],
     Temperature = 0.2f
 };

 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║        🔍  AI Research Agent  🔍        ║");
 Console.WriteLine("╠══════════════════════════════════════════╣");
 Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.Write("Research topic> ");
     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notes.Clear();

     List<ChatMessage> messages =
     [
         new(ChatRole.System, """
             You are a research agent. When the user gives you a topic:
             1. Use web_search to find relevant information (make 2-3 searches with varied queries).
             2. Use add_note to save key findings as you go.
             3. Use list_notes to review what you have collected.
             4. Finally, write a concise summary of your research with references.
             Always cite your sources with URLs when available.
             """),
         new(ChatRole.User, $"Research this topic: {topic}")
     ];

     Console.WriteLine($"\n🔎 Researching \"{topic}\"...\n");

     const int maxIterations = 20;
     for (int i = 0; i < maxIterations; i++)
     {
         var response = await client.GetResponseAsync(messages, chatOptions);

         // Append all response messages to the conversation
         foreach (var msg in response.Messages)
             messages.Add(msg);

         // Check whether any message contains a tool call (needs another round)
         bool hasToolCall = response.Messages
             .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

         if (!hasToolCall)
         {
             // Final assistant text – print and break
             var finalText = response.Messages
                 .Where(m => m.Role == ChatRole.Assistant)
                 .SelectMany(m => m.Contents.OfType<TextContent>())
                 .LastOrDefault()?.Text;

             Console.WriteLine("═══════════════ Research Summary ═══════════════\n");
             Console.WriteLine(finalText ?? "(No summary produced.)");
             Console.WriteLine("\n════════════════════════════════════════════════\n");
             break;
         }

         // Log tool calls for visibility
         foreach (var fc in response.Messages.SelectMany(m => m.Contents.OfType<FunctionCallContent>()))
             Console.WriteLine($"  🛠  {fc.Name}({Truncate(fc.Arguments?.ToString(), 80)})");
     }
 }

 Console.WriteLine("Goodbye!");
 return;

 static string Truncate(string? s, int max) =>
     s is null ? "" : s.Length <= max ? s : s[..max] + "…";

 // --- Supporting types --------------------------------------------------------

 sealed class NoteStore
 {
     private readonly List<Note> _notes = [];
     public int Count => _notes.Count;
     public IReadOnlyList<Note> All => _notes;
     public void Add(string title, string content) => _notes.Add(new(title, content));
     public void Clear() => _notes.Clear();
 }

 record Note(string Title, string Content);

 sealed class WebSearchService(string? apiKey, string? engineId, bool live)
 {
     private static readonly HttpClient Http = new();

     public async Task<string> SearchAsync(string query)
     {
         if (!live)
             return SimulateSearch(query);

         // Google Custom Search JSON API
         var url = $"https://www.googleapis.com/customsearch/v1?key={apiKey}&cx={engineId}&q={Uri.EscapeDataString(query)}&num=5";
         var json = await Http.GetFromJsonAsync<JsonElement>(url);
         var items = json.GetProperty("items");
         var results = new List<string>();
         foreach (var item in items.EnumerateArray())
         {
             var title = item.GetProperty("title").GetString();
             var snippet = item.GetProperty("snippet").GetString();
             var link = item.GetProperty("link").GetString();
             results.Add($"Title: {title}\nSnippet: {snippet}\nURL: {link}");
         }
         return string.Join("\n---\n", results);
     }

     private static string SimulateSearch(string query)
     {
         return $"""
             [Simulated search results for "{query}"]

             Title: Overview of {query} - Wikipedia
             Snippet: {query} is a broad topic that encompasses many areas of study. Recent developments have shown significant progress in both theoretical and practical applications.
             URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
             ---
             Title: Latest Research on {query}
             Snippet: Researchers have made breakthroughs in {query}, with new findings published in leading journals. Key areas include efficiency improvements and novel methodologies.
             URL: https://example.com/research/{Uri.EscapeDataString(query)}
             ---
             Title: {query}: A Practical Guide
             Snippet: This comprehensive guide covers the fundamentals of {query}, including best practices, common pitfalls, and expert recommendations for getting started.
             URL: https://example.com/guide/{Uri.EscapeDataString(query)}
             """;
     }
 }

